package za.co.loopmanager;

import android.app.Activity;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.graphics.drawable.RippleDrawable;
import android.view.Gravity;
import android.view.View;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import com.google.android.material.bottomsheet.BottomSheetBehavior;
import com.google.android.material.bottomsheet.BottomSheetDialog;
import za.co.bacy.ui.BrandFonts;
import za.co.bacy.ui.InstrumentIcon;

/** Colour-coded native payment sheets. Financial actions remain with the enrolled account controller. */
final class AccountSheets {
 static final int INK=0xff173832,MUTED=0xff40594f,TEAL=0xff075e55,CORAL=0xffffc9ad,GOLD=0xffffe197,MINT=0xffcff0df,PAPER=0xfffffdf8,LINE=0xffdce5df;
 private final Activity activity;final BottomSheetDialog dialog;final LinearLayout body;
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private AccountSheets(Activity a,String title,String subtitle){
  activity=a;dialog=new BottomSheetDialog(a);ScrollView scroll=new ScrollView(a);scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);scroll.setBackground(shape(PAPER,28,0));scroll.setClipToOutline(true);body=col();body.setPadding(dp(22),dp(12),dp(22),dp(26));scroll.addView(body);
  View handle=new View(a);handle.setBackground(shape(LINE,3,0));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(36),dp(4));hp.gravity=Gravity.CENTER;hp.bottomMargin=dp(18);body.addView(handle,hp);
  LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);TextView name=text(title,27,INK,true);name.setTypeface(BrandFonts.heading(a));name.setAccessibilityHeading(true);heading.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView close=text("×",27,INK,false);close.setGravity(Gravity.CENTER);close.setContentDescription("Close sheet");close.setFocusable(true);close.setBackground(shape(0xffedf2ed,24,0));close.setOnClickListener(v->dialog.dismiss());heading.addView(close,new LinearLayout.LayoutParams(dp(44),dp(44)));body.addView(heading);gap(7);body.addView(text(subtitle,13,MUTED,false));gap(20);
  dialog.setContentView(scroll);dialog.setOnShowListener(d->{View sheet=dialog.findViewById(com.google.android.material.R.id.design_bottom_sheet);if(sheet!=null){sheet.setBackgroundColor(Color.TRANSPARENT);BottomSheetBehavior<View> behavior=BottomSheetBehavior.from(sheet);behavior.setMaxHeight((int)(a.getResources().getDisplayMetrics().heightPixels*.9f));behavior.setSkipCollapsed(true);behavior.setState(BottomSheetBehavior.STATE_EXPANDED);}if(dialog.getWindow()!=null)dialog.getWindow().setDimAmount(.32f);});
 }
 private LinearLayout col(){LinearLayout l=new LinearLayout(activity);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private TextView text(String value,int size,int color,boolean bold){TextView v=new TextView(activity);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setTypeface(BrandFonts.sans(activity,bold));v.setLineSpacing(dp(2),1);v.setIncludeFontPadding(false);return v;}
 private GradientDrawable shape(int fill,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 private void gap(int height){body.addView(new View(activity),new LinearLayout.LayoutParams(1,dp(height)));}
 private View action(String title,String detail,String icon,int fill,Runnable run){
  LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(15),dp(16),dp(14),dp(16));row.setMinimumHeight(dp(76));row.setBackground(new RippleDrawable(ColorStateList.valueOf(0x1a075e55),shape(fill,18,fill==PAPER?LINE:0),null));row.setFocusable(true);row.setContentDescription(title);row.setOnClickListener(v->{dialog.dismiss();run.run();});
  row.addView(new InstrumentIcon(activity,icon,TEAL),new LinearLayout.LayoutParams(dp(26),dp(26)));LinearLayout copy=col();copy.addView(text(title,15,INK,true));if(detail!=null&&!detail.isEmpty()){View space=new View(activity);copy.addView(space,new LinearLayout.LayoutParams(1,dp(5)));copy.addView(text(detail,12,MUTED,false));}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=dp(14);cp.rightMargin=dp(8);row.addView(copy,cp);TextView arrow=text("›",26,TEAL,false);row.addView(arrow);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(10);body.addView(row,rp);return row;
 }
 private void pair(String a,String subA,String iconA,Runnable runA,String b,String subB,String iconB,Runnable runB){LinearLayout row=new LinearLayout(activity);String[] titles={a,b},subtitles={subA,subB},icons={iconA,iconB};Runnable[] actions={runA,runB};for(int i=0;i<2;i++){final int which=i;LinearLayout tile=col();tile.setPadding(dp(14),dp(16),dp(14),dp(16));tile.setMinimumHeight(dp(112));tile.setBackground(new RippleDrawable(ColorStateList.valueOf(0x1a075e55),shape(PAPER,18,LINE),null));tile.setFocusable(true);tile.setContentDescription(titles[i]);tile.setOnClickListener(v->{dialog.dismiss();actions[which].run();});tile.addView(new InstrumentIcon(activity,icons[i],TEAL),new LinearLayout.LayoutParams(dp(24),dp(24)));TextView title=text(titles[i],13,INK,true);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.topMargin=dp(12);tile.addView(title,tp);TextView sub=text(subtitles[i],11,MUTED,false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(5);tile.addView(sub,sp);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i==0)p.rightMargin=dp(10);row.addView(tile,p);}body.addView(row);}
 private void notice(String title,String message,int fill,String icon){LinearLayout card=col();card.setPadding(dp(18),dp(20),dp(18),dp(20));card.setBackground(shape(fill,20,0));card.addView(new InstrumentIcon(activity,icon,TEAL),new LinearLayout.LayoutParams(dp(30),dp(30)));View space=new View(activity);card.addView(space,new LinearLayout.LayoutParams(1,dp(14)));card.addView(text(title,22,INK,true));TextView description=text(message,14,INK,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(9);card.addView(description,p);body.addView(card);gap(16);}
 private void detail(String label,String value){LinearLayout row=col();row.setPadding(dp(2),dp(13),dp(2),dp(13));row.addView(text(label,12,MUTED,false));TextView reading=text(value,16,INK,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(5);row.addView(reading,p);body.addView(row);View line=new View(activity);line.setBackgroundColor(LINE);body.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}
 static AccountSheets panel(Activity a,String title,String subtitle){return new AccountSheets(a,title,subtitle);}
 AccountSheets note(String title,String message,int fill,String icon){notice(title,message,fill,icon);return this;}
 AccountSheets content(View view){body.addView(view);gap(16);return this;}
 AccountSheets line(String label,String value){detail(label,value);return this;}
 AccountSheets option(String title,String detail,String icon,int fill,Runnable run){action(title,detail,icon,fill,run);return this;}
 View formAction(String title,Runnable run){View v=AppControls.action(activity,title,"","message",MINT,run);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);body.addView(v,p);return v;}
 BottomSheetDialog show(){dialog.show();return dialog;}
 static BottomSheetDialog confirm(Activity a,String title,String message,String primary,Runnable action){return panel(a,title,"Please review before continuing").note(title,message,GOLD,"shield").option(primary,"","check",CORAL,action).show();}
 static BottomSheetDialog banks(Activity a,java.util.List<BankApps.Choice> banks,java.util.function.Consumer<BankApps.Choice> open){AccountSheets s=panel(a,"Your banking apps","Only installed, approved banking apps are shown");for(BankApps.Choice bank:banks)s.option(bank.label,"Open securely · return with Back or Recents","bank",MINT,()->open.accept(bank));return s.show();}
 static BottomSheetDialog eft(Activity a,org.json.JSONObject bank,String reference,String amount,Runnable open,Runnable copy){AccountSheets s=panel(a,"Bank transfer","Manual EFT · approval follows settlement review");s.note(amount,"Use your exact payment reference. Your paid time changes after the administrator confirms the bank funds.",GOLD,"bank");if(bank!=null&&!bank.optString("account_number").isEmpty()){for(String[] f:new String[][]{{"Bank","bank"},{"Account holder","account_holder"},{"Account number","account_number"},{"Branch code","branch_code"}}){String value=bank.optString(f[1]);s.option(f[0]+": "+value,"Tap to copy","copy",PAPER,()->{a.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(android.content.ClipData.newPlainText(f[0],value));AppControls.notice(a,f[0]+" copied");});}}else s.note("Account details needed","Ask your administrator for verified bank details before paying.",CORAL,"help");s.line("Payment reference",reference);s.option("Open banking app","Choose your installed bank","bank",MINT,open);s.option("Copy reference",reference,"copy",PAPER,copy);return s.show();}
 static BottomSheetDialog payments(Activity a,String amount,Runnable card,Runnable eft,Runnable manual,Runnable status,Runnable fresh){AccountSheets s=new AccountSheets(a,"Make a payment",amount+" · one payment adds 30 days");s.action("Card payment","Secure checkout with iKhokha","payment",CORAL,card);s.action("Instant EFT / Ozow","Choose your bank on secure checkout","bank",GOLD,eft);s.action("Bank transfer","Account details and your EFT reference","bank",MINT,manual);s.gap(4);s.pair("Payment status","Check confirmation","history",status,"Fresh payment link","Replace failed checkout","refresh",fresh);s.dialog.show();return s.dialog;}
 static BottomSheetDialog account(Activity a,String amount,String due,String grace,String reference,Runnable pay,Runnable copy){return account(a,amount,due,grace,reference,pay,copy,null);}
 static BottomSheetDialog account(Activity a,String amount,String due,String grace,String reference,Runnable pay,Runnable copy,Runnable summary){AccountSheets s=new AccountSheets(a,"Your plan","Your verified account details");s.notice(amount,"Every 30 days",MINT,"phone");s.detail("Paid until",due);s.detail("Grace ends",grace);s.detail("Your EFT reference",reference);s.gap(18);s.action("Make a payment","Card, Instant EFT or bank transfer","payment",CORAL,pay);s.action("Copy payment reference",reference,"copy",PAPER,copy);if(summary!=null)s.action("Copy payment summary","Total, verified paid amount, balance and progress","copy",GOLD,summary);s.dialog.show();return s.dialog;}
 static BottomSheetDialog status(Activity a,String state,boolean freshNeeded,String message,Runnable check,Runnable fresh,Runnable history){boolean paid="paid".equals(state);AccountSheets s=new AccountSheets(a,"Payment update","Confirmation comes directly from iKhokha");s.notice(paid?"Payment verified":freshNeeded?"A fresh link is needed":"review_required".equals(state)?"Needs a review":"none".equals(state)?"No checkout yet":"Waiting for confirmation",message,paid?MINT:freshNeeded?CORAL:GOLD,paid?"shield":"payment");if(paid)s.action("View payment history","Your approved payment records","history",MINT,history);else{s.action("Check again","Refresh the provider's payment status","refresh",MINT,check);if("pending".equals(state)||"failed".equals(state))s.action("Get a fresh payment link","Use if checkout failed and you were not debited","payment",CORAL,fresh);}s.dialog.show();return s.dialog;}
 static BottomSheetDialog fresh(Activity a,Runnable renew,Runnable check){AccountSheets s=new AccountSheets(a,"A fresh checkout","Keep your existing payment safe");s.notice("Check before you retry","If your bank already debited you, check payment status first. Otherwise we will verify the old attempt before creating a new link for the amount due.",GOLD,"shield");s.action("Get fresh payment link","The server checks the old attempt first","payment",CORAL,renew);s.action("Check existing payment","Use this if your bank shows a debit","history",MINT,check);s.dialog.show();return s.dialog;}
 static BottomSheetDialog error(Activity a,String message){AccountSheets s=new AccountSheets(a,"Let's check that","Your phone account");s.notice("Needs your attention",message,CORAL,"help");s.action("Got it","Return to your account","home",MINT,()->{});s.dialog.show();return s.dialog;}
}
